insert into tmp_ontology_skills (skill_id, description)
values
  ('AT1', 'Apply Invertendo: if a:b = c:d, then b:a = d:c'),
  ('AT2', 'Apply Alternendo: if a:b = c:d, then a:c = b:d'),
  ('AT3', 'Apply Componendo: if a/b = c/d, then (a+b)/b = (c+d)/d'),
  ('AT4', 'Apply Dividendo: if a/b = c/d, then (a-b)/b = (c-d)/d'),
  ('AT5', 'Apply Componendo-Dividendo: if a/b = c/d, then (a+b)/(a-b) = (c+d)/(c-d)'),
  ('CI1', 'Understand how interest compounds: each period''s profit is added to the principal'),
  ('CI10', 'Find original principal P given A, R, and T under CI'),
  ('CI11', 'Find rate R given P, A, and T under CI (integer T = 2)'),
  ('CI12', 'Find T given P, A, and R under CI by trial or pattern (small integer T)'),
  ('CI13', 'Compute CI for T = 1 and verify it equals SI for the same values'),
  ('CI14', 'Compare CI and SI for same P, R, T and explain the difference'),
  ('CI15', 'Calculate the difference CI − SI = P(R/100)² for T = 2'),
  ('CI16', 'Apply CI to real-world contexts: population growth, depreciation, investment'),
  ('CI17', 'Solve two-step word problems requiring CI computation and comparison'),
  ('CI2', 'Compute CI manually year-by-year for T = 2 and T = 3'),
  ('CI3', 'State the annual compounding formula: A = P(1 + R/100)^T'),
  ('CI4', 'Evaluate (1 + R/100)^T for integer T using repeated multiplication'),
  ('CI5', 'Compute A and CI using A = P(1 + R/100)^T for annual compounding'),
  ('CI6', 'Identify the compounding period (annual, half-yearly, quarterly)'),
  ('CI7', 'Adjust rate and time for half-yearly compounding (R→R/2, T→2T)'),
  ('CI8', 'Adjust rate and time for quarterly compounding (R→R/4, T→4T)'),
  ('CI9', 'Compute A and CI for half-yearly and quarterly compounding periods'),
  ('LG1', 'List multiples of a given number'),
  ('LG10', 'Find HCF of two numbers by factor enumeration (list all factors, pick greatest common)'),
  ('LG11', 'Find HCF of two numbers by common prime factors (prime factorize both, multiply common primes)'),
  ('LG12', 'Find HCF of two numbers by division method (Euclidean algorithm)'),
  ('LG13', 'Find LCM of two numbers by listing and comparing multiples'),
  ('LG14', 'Find LCM of two numbers by prime factorization (take highest power of each prime)'),
  ('LG15', 'Find LCM of two numbers by Euclid''s ladder method (successive division by common/remaining primes)'),
  ('LG16', 'Find HCF of three or more numbers'),
  ('LG17', 'Find LCM of three or more numbers'),
  ('LG18', 'Apply HCF to equal-distribution problems (e.g., divide items into largest equal groups)'),
  ('LG19', 'Apply LCM to scheduling and synchronization problems (e.g., when two periodic events next coincide)'),
  ('LG2', 'Check exact divisibility of one number by another'),
  ('LG20', 'Use the relationship: Product of two numbers = HCF × LCM'),
  ('LG21', 'Find HCF and LCM of fractions: HCF=(HCF of numerators)/(LCM of denominators); LCM=(LCM of numerators)/(HCF of denominators)'),
  ('LG22', 'Find an unknown number given the other number, the HCF, and the LCM, using the product relationship'),
  ('LG23', 'Find HCF and LCM of decimal fractions (equalize decimal places, treat as integers, reposition decimal point)'),
  ('LG3', 'List all factors of a number by trial division'),
  ('LG4', 'Apply divisibility rules for 2, 3, 4, 5, and 9'),
  ('LG5', 'Identify whether a number is prime or composite'),
  ('LG6', 'Find common multiples of two numbers'),
  ('LG7', 'Find common factors of two numbers'),
  ('LG8', 'Express a number as a product of prime factors (factor tree or repeated division)'),
  ('LG9', 'Identify whether two or more numbers are co-prime'),
  ('PC1', 'Define percentage as parts per hundred'),
  ('PC2', 'Express a fraction as a percentage'),
  ('PC3', 'Express a percentage as a fraction'),
  ('PC4', 'Express a decimal as a percentage'),
  ('PC5', 'Express a percentage as a decimal'),
  ('PC6', 'Convert fluently between ratio, fraction, decimal, and percentage'),
  ('PCA1', 'Calculate a percentage of a given quantity'),
  ('PCA2', 'Express one quantity as a percentage of another'),
  ('PCA3', 'Find the original value given a percentage of it'),
  ('PCA4', 'Calculate percentage increase'),
  ('PCA5', 'Calculate percentage decrease'),
  ('PCA6', 'Calculate percentage change (increase or decrease) between two values'),
  ('PF1', 'Define proportion as the equality of two ratios (a:b = c:d)'),
  ('PF2', 'Identify the four terms of a proportion and distinguish means from extremes'),
  ('PF3', 'Apply the cross-multiplication property (product of means = product of extremes)'),
  ('PF4', 'Determine if four numbers are in proportion'),
  ('PF5', 'Find the missing fourth term in a proportion'),
  ('PF6', 'Define and identify continued proportion (a:b = b:c, so b² = ac)'),
  ('PF7', 'Calculate the mean proportional and third proportional in a continued proportion'),
  ('PL1', 'Identify Cost Price (CP) in a word problem, including overhead costs (rent, transport, etc.)'),
  ('PL10', 'Determine the required selling rate (items per taka) to achieve a target profit%'),
  ('PL11', 'Find CP when two different SP scenarios and their difference in value are given'),
  ('PL12', 'Find CP when SP and total amount are both expressed as proportional parts'),
  ('PL13', 'Find original CP through a chain of successive profit percentages (e.g., wholesaler → retailer)'),
