  ('PL5', 'Calculate profit or loss percentage on CP'),
  ('PL6', 'Calculate SP given CP and a profit or loss percentage'),
  ('PL7', 'Calculate CP given SP and a profit or loss percentage'),
  ('PL8', 'Calculate CP or SP per unit from a bulk rate'),
  ('PL9', 'Calculate overall profit% or loss% when buying and selling are both expressed in unit-rate form'),
  ('PRE1', 'Identify and write whole numbers up to large values (lakhs/crores)'),
  ('PRE2', 'Add and subtract whole numbers'),
  ('PRE3', 'Multiply whole numbers'),
  ('PRE4', 'Divide whole numbers (including remainders and non-integer results)'),
  ('PRE5', 'Convert between fractions and decimals'),
  ('PRE6', 'Multiply and divide decimal numbers'),
  ('PRE8', 'Basic algebraic manipulation — solve for a single variable'),
  ('PRE9', 'Set up and solve a system of two linear equations with two unknowns'),
  ('RF1', 'Define ratio as a comparison of two quantities of the same kind and unit by division'),
  ('RF10', 'Calculate the compound (mixed) ratio of two or more simple ratios'),
  ('RF11', 'Divide a quantity in a given ratio'),
  ('RF2', 'Identify antecedent and consequent in a ratio'),
  ('RF3', 'Express a ratio as a fraction and vice versa'),
  ('RF4', 'Convert quantities to a common unit before forming a ratio'),
  ('RF5', 'Find equivalent ratios'),
  ('RF6', 'Simplify a ratio to lowest terms using HCF'),
  ('RF7', 'Compare two quantities using ratio'),
  ('RF8', 'Distinguish between ratio of less inequality, greater inequality, and unit ratio'),
  ('RF9', 'Form the inverse ratio by interchanging antecedent and consequent'),
